let opening;
export function openDatabase(){return opening??=new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('Le stockage du navigateur est indisponible.'));return;}const request=indexedDB.open('onde-projects',1);request.onupgradeneeded=()=>{const db=request.result;db.createObjectStore('projects',{keyPath:'id'});db.createObjectStore('contents',{keyPath:'id'});};request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>{db.close();opening=null;};resolve(db);};request.onerror=()=>{opening=null;reject(request.error);};request.onblocked=()=>{reject(Error('Fermez les autres onglets Onde puis réessayez.'));opening=null;};});}
export async function listProjects(){const db=await openDatabase();return new Promise((resolve,reject)=>{const req=db.transaction('projects').objectStore('projects').getAll();req.onsuccess=()=>resolve(req.result.sort((a,b)=>b.savedAt-a.savedAt));req.onerror=()=>reject(req.error);});}
export async function readProject(id){const db=await openDatabase();return new Promise((resolve,reject)=>{const req=db.transaction('contents').objectStore('contents').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
export async function writeProject(record,expectedRevision=0){const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(['projects','contents'],'readwrite');let error,revision;const store=tx.objectStore('projects'),req=store.get(record.id);req.onsuccess=()=>{const old=req.result;if((old?.revision||0)!==expectedRevision){error=Error('Ce projet a changé dans un autre onglet. Utilisez « Sauvegarder sous » pour conserver votre montage.');tx.abort();return;}revision=expectedRevision+1;const savedAt=Date.now(),full={...record,revision,savedAt};store.put({id:record.id,name:record.state.name,revision,savedAt,bytes:record.assets.reduce((n,a)=>n+a.blob.size,0),tracks:record.state.tracks.length,duration:Math.max(0,...record.state.clips.map(c=>c.start+c.duration))});tx.objectStore('contents').put(full);};tx.oncomplete=()=>resolve(revision);tx.onerror=()=>reject(error||tx.error||Error('Enregistrement impossible.'));tx.onabort=()=>reject(error||tx.error||Error('Enregistrement annulé.'));});}
export async function deleteProject(id){const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(['projects','contents'],'readwrite');tx.objectStore('projects').delete(id);tx.objectStore('contents').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
